output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper must first take the available cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "cart_available_at_entry": {
          "and": [
            "entry_cart_station",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "cart_available_at_entry",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items may only be picked up while the shopper is holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "return_cart_after_use",
    "text": "After taking a cart, the shopper must return it to the cart-return point at the front-left of the store.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)"
      },
      "events": {
        "take_any_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_front_left": {
          "pre": {
            "and": [
              "hasCart",
              "cart_return_point",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_any_cart",
      "discharge": "return_cart_to_front_left"
    }
  },
  {
    "id": "park_cart_only_at_return",
    "text": "A shopper is forbidden from leaving a cart anywhere except the designated return point at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "designated_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper must not leave the store while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is not allowed to carry merchandise by hand instead of using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "pickup_into_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_into_hand"
        ]
      }
    }
  },
  {
    "id": "no_carts_in_checkout_zone",
    "text": "Shopping carts are forbidden in the eastern checkout and exit zone of the store.",
    "abstraction": {
      "state_properties": {
        "checkout_exit_zone": {
          "or": [
            "at(7,0)",
            "at(8,0)",
            "at(9,0)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_exit_zone": {
          "and": [
            "hasCart",
            "checkout_exit_zone"
          ]
        }
      },
      "events": {
        "enter_checkout_zone_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "checkout_exit_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_exit_zone",
          "enter_checkout_zone_with_cart"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the return point, the shopper must not resume shopping or perform further store interactions.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "interact_after_cart_return": {
          "pre": {
            "and": [
              "cart_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "interact_after_cart_return"
    }
  }
]
